import assert from "node:assert/strict";
import { default as __ns1_epsilon } from "./src/epsilon.js";
import { default as __ns1_kMeansCluster } from "./src/k_means_cluster.js";
const ss = Object.freeze({ epsilon: __ns1_epsilon, kMeansCluster: __ns1_kMeansCluster });
{
function nonRNG() {
    return 1.0 - ss.epsilon;
}
{
{
const points = Object.freeze([[0.5]]);
        const { labels, centroids } = ss.kMeansCluster(points, 1, nonRNG);
        assert.deepEqual(labels, [0]);
        assert.deepEqual(centroids, [[0.5]]);
}
}
}

